<?php declare(strict_types=1);use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;defined('_JEXEC')or die;$d=$this->ranking;?>
<div class="com-joomleague-eventranking"><?php if(isset($d['error'])):?><div class="alert alert-warning"><?php echo Text::_($d['error']);?></div><?php else:?><h1><?php echo Text::sprintf('COM_JOOMLEAGUE_EVENTRANKING_PAGE_TITLE',htmlspecialchars((string)$d['project']->name,ENT_QUOTES,'UTF-8'));?></h1><?php if($d['definitions']===[]):?><div class="alert alert-info"><?php echo Text::_('COM_JOOMLEAGUE_EVENTRANKING_EMPTY');?></div><?php else:?><nav class="nav nav-pills gap-2 mb-4" aria-label="<?php echo Text::_('COM_JOOMLEAGUE_EVENTRANKING_EVENT_LABEL');?>"><?php foreach($d['definitions']as$def):$active=(string)$def->event_code===(string)$d['selected_code'];?><a class="nav-link<?php echo$active?' active':'';?>" href="<?php echo Route::_('index.php?option=com_joomleague&view=eventranking&project_id='.(int)$d['project']->id.'&event_code='.rawurlencode((string)$def->event_code));?>"><?php echo Text::_((string)$def->name_key);?></a><?php endforeach;?></nav><?php if($d['rows']===[]):?><div class="alert alert-info"><?php echo Text::_('COM_JOOMLEAGUE_EVENTRANKING_NO_VALUES');?></div><?php else:?><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th class="text-center"><?php echo Text::_('COM_JOOMLEAGUE_EVENTRANKING_RANK');?></th><th><?php echo Text::_('COM_JOOMLEAGUE_EVENTRANKING_PARTICIPANT');?></th><th class="text-center"><?php echo Text::_('COM_JOOMLEAGUE_EVENTRANKING_APPEARANCES');?></th><th class="text-end"><?php echo Text::_('COM_JOOMLEAGUE_EVENTRANKING_VALUE');?></th></tr></thead><tbody><?php foreach($d['rows']as$r):$url=(string)$r->target_kind==='person'?Route::_('index.php?option=com_joomleague&view=person&person_id='.(int)$r->target_id):((string)$r->target_kind==='team'?Route::_('index.php?option=com_joomleague&view=team&team_id='.(int)$r->target_id):Route::_('index.php?option=com_joomleague&view=participant&project_id='.(int)$d['project']->id.'&entry_id='.(int)$r->target_id));?><tr><td class="text-center fw-semibold"><?php echo(int)$r->rank;?></td><th><a href="<?php echo$url;?>"><?php echo htmlspecialchars((string)$r->display_name,ENT_QUOTES,'UTF-8');?></a></th><td class="text-center"><?php echo(int)$r->appearances;?></td><td class="text-end fw-semibold"><?php echo(int)$r->total_value;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;endif;endif;?></div>
